/* UI is intentionally separate from the forwarding model in network.js. */
'use strict';
const N=window.AeroNet;
const $=(s,el=document)=>el.querySelector(s);
const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=N.makeScenario('enterprise'),engine=new N.Engine(state),selected='r1',inspectorTab='config',selectedInterface='GigabitEthernet0/0';
let tool='select',cableStart=null,zoom=1,logTab='events',lastPacket=null,animationToken=0,toastTimer,historyIndex=0;
const scenarios=[
 {id:'enterprise',icon:'✈',name:'Expanded airport · EIGRP',desc:'Four routers, four LANs, 36 devices and a redundant WAN ring. Disable a serial link to explore failover.',exp:'EXPERIMENT 11'},
 {id:'remote',icon:'⌘',name:'Telnet & SSH management',desc:'Configure VTY access and open a remote router console from any reachable host.',exp:'EXPERIMENT 12'},
 {id:'ppp',icon:'↔',name:'PPP serial WAN',desc:'Matching PPP encapsulation on both ends; OSPF supplies routes. Break a link by changing one end to HDLC.',exp:'EXPERIMENT 09A'},
 {id:'hdlc',icon:'↔',name:'HDLC serial WAN',desc:'Cisco HDLC on serial WAN links. Compare encapsulation and test end-to-end connectivity.',exp:'EXPERIMENT 09B'},
 {id:'bgp',icon:'⇄',name:'BGP autonomous systems',desc:'AS 65001, 65002 and 65003 exchange LAN prefixes using reciprocal eBGP neighbors.',exp:'EXPERIMENT 10'},
 {id:'basic',icon:'⌘',name:'Airport basic LAN',desc:'Explore three LANs, IP configuration, cables and gateways. Remote LANs begin without routes.',exp:'EXPERIMENTS 01–04'},
 {id:'p2p',icon:'↔',name:'Peer-to-peer link',desc:'Two check-in desks connected directly by a copper cross-over cable. No switch or gateway required.',exp:'EXPERIMENT 02'},
 {id:'static',icon:'⇢',name:'Static & default routing',desc:'Follow explicit next hops and default routes from the terminal to the ISP.',exp:'EXPERIMENT 05'},
 {id:'nat-static',icon:'⇆',name:'Static NAT',desc:'Map Check-in Desk 01 to 172.16.0.10. Test access in both directions.',exp:'EXPERIMENT 06A'},
 {id:'nat-pool',icon:'⧉',name:'Dynamic NAT pool',desc:'Allocate public-facing addresses from a five-address pool as hosts send traffic.',exp:'EXPERIMENT 06B'},
 {id:'nat',icon:'⇌',name:'NAT overload · PAT',desc:'Let the check-in and security LANs share the terminal router’s outside address.',exp:'EXPERIMENT 06 · EXTENSION'},
 {id:'rip1',icon:'⌁',name:'RIP version 1',desc:'Explore classful distance-vector routing and automatic summaries across major networks.',exp:'EXPERIMENT 07'},
 {id:'rip2',icon:'⌁',name:'RIP version 2',desc:'Share subnet prefixes between routers using hop-count metrics.',exp:'EXPERIMENT 07'},
 {id:'ospf',icon:'◎',name:'Single-area OSPF',desc:'A ready-to-explore airport. All router interfaces participate in backbone area 0.',exp:'EXPERIMENT 08A'},
 {id:'multi',icon:'◉',name:'Multi-area OSPF',desc:'Terminal area 1 and tower area 2 connect through area 0. Inspect ABRs and inter-area routes.',exp:'EXPERIMENT 08B'}
];
const experiments=[
 {title:'Networking fundamentals',topic:'Commands & cables',scenario:'basic',body:'Identify routers, switches and hosts. Compare straight-through, cross-over and serial DCE cables. Run ping and traceroute, then inspect the forwarding steps.'},
 {title:'P2P, LAN & topologies',topic:'P2P & LAN topologies',scenario:'p2p',body:'Start with a direct cross-over link between two PCs. Load Airport basic LAN to explore star LANs and a hybrid topology. Add devices, move them, and connect free ports.'},
 {title:'Router console',topic:'Router console',scenario:'basic',body:'Select a router and open CLI. Enter enable, configure terminal, interface g0/0, then no shutdown. Use show running-config and show ip interface brief to inspect the result.'},
 {title:'IP addressing & subnetting',topic:'IP addressing & subnets',scenario:'basic',body:'Configure host addresses and router interfaces. Calculate /27 LANs and /30 WAN links in the subnet calculator. Verify the gateway is on the host subnet.'},
 {title:'Static & default routing',topic:'Static & default routing',scenario:'static',body:'Inspect S routes and S* default routes. Add a destination network, mask and next hop from Routing tables, or use ip route in CLI. The reply also needs a valid route.'},
 {title:'Network address translation',topic:'NAT configuration',scenario:'nat',body:'Compare Static NAT, Dynamic NAT pool and PAT scenarios. Mark inside/outside interfaces on the Terminal Router. Ping the Flight API Server and inspect the translation table.'},
 {title:'RIP versions 1 & 2',topic:'RIP v1 & v2',scenario:'rip2',body:'Select RIP v1 or v2 in the Routing tab. Routers advertise participating connected networks. Version 1 summarizes across major network boundaries; version 2 preserves subnet masks. Peers must use the same version in this model.'},
 {title:'OSPF single & multi-area',topic:'OSPF routing',scenario:'ospf',body:'Inspect FULL neighbors and cost-based O routes. Load Multi-area OSPF to see O IA routes. Area 1 and area 2 attach to backbone area 0. Change a WAN area on one end to break the adjacency.'},
 {title:'PPP & HDLC serial encapsulation',topic:'PPP & HDLC',scenario:'ppp',body:'Load PPP serial WAN or HDLC serial WAN. Select a router, open Config and change serial encapsulation. Both ends must match. Use show interfaces in CLI, then ping across the airport. PPP authentication and negotiation timers are abstracted.'},
 {title:'Border Gateway Protocol',topic:'BGP routing',scenario:'bgp',body:'Load BGP autonomous systems. Each router has a distinct AS number. Open Routing to edit neighbors and exact connected network advertisements. Reciprocal remote AS values establish sessions. Inspect AS paths with show ip bgp and session state with show ip bgp summary. This model supports direct eBGP, shortest AS path and loop prevention; iBGP, policies and timers are abstracted.'},
 {title:'Enhanced Interior Gateway Routing Protocol',topic:'EIGRP routing',scenario:'enterprise',body:'Four routers in AS 100 exchange classless prefixes. Inspect D routes and EIGRP neighbors in Routing. Disable a WAN interface to observe the alternate route. AS and participating networks must match. The model uses fixed Ethernet/serial teaching costs and immediate shortest-path recomputation; full DUAL, feasible successors and timers are abstracted.'},
 {title:'Telnet & SSH remote access',topic:'Telnet & SSH',scenario:'remote',body:'Open Remote access from a router Config tab. Configure domain, local login and VTY transports. Demo account: admin / AirportLab123. Connect from a reachable host using Telnet or SSH. Try invalid credentials, disabled transport or disconnected interfaces. Sessions run locally in your browser; no real network service is exposed.'}
];
const time=()=>new Date().toLocaleTimeString('en-GB',{hour12:false});
function notify(message,error=false){const t=$('#toast');t.textContent=message;t.style.background=error?'#945d52':'#233f53';t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function log(message,kind='CONFIG',error=false){state.events.unshift({time:time(),message,kind,error});state.events=state.events.slice(0,100);$('#last-status').textContent=message;renderActivity();}
function changed(message){state.translations=[];renderTopology();renderMetrics();if(message)log(message);}
function shortPort(name){return name.replace('GigabitEthernet','G').replace('FastEthernet','Fa').replace('Serial','Se');}
function iconSVG(type){
 if(type==='router')return '<ellipse cx="0" cy="-8" rx="24" ry="9"/><path d="M-24-8v13c0 5 11 10 24 10s24-5 24-10V-8"/><path d="m-14-9 8-3-2 5m8-6 1 7 5-2m-19 8 7 2-5 3m14-4 7-3-2 5"/>';
 if(type==='switch')return '<rect x="-27" y="-12" width="54" height="24" rx="4"/><path d="M-22 1h44M-20-5h5m4 0h5m4 0h5m4 0h5m4 0h5"/><path d="M-20 6h3m3 0h3m3 0h3m3 0h3m3 0h3m3 0h3"/>';
 if(type==='server')return '<rect x="-14" y="-23" width="28" height="44" rx="4"/><path d="M-9-13H9M-9-4H9M-9 5H9"/><circle cx="7" cy="14" r="1.5"/>';
 return '<rect x="-23" y="-20" width="46" height="31" rx="3"/><path d="M-4 12v9m8-9v9m-15 1h22M-18 6h36"/>';
}
function renderTopology(){
 const svg=$('#topology');
 const peer=state.scenario==='p2p',width=peer?1100:state.enterprise?2100:1600,height=peer?660:820;
 svg.style.aspectRatio=state.enterprise?'2100 / 820':'';
 svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
 svg.parentElement.classList.toggle('expanded',!peer);
 const zones=peer?'<rect class="zone-rect" x="190" y="180" width="700" height="260"/><text class="zone-label" x="220" y="212">PEER-TO-PEER · CHECK-IN DESKS</text>':'<rect class="zone-rect" x="20" y="305" width="880" height="495"/><text class="zone-label" x="44" y="331">01 / PASSENGER TERMINAL</text><text class="zone-sub" x="44" y="350">8 CHECK-IN DESKS · 6 SECURITY PCS</text><rect class="zone-rect" x="920" y="305" width="660" height="495"/><text class="zone-label" x="944" y="331">02 / AIRPORT OPERATIONS</text><text class="zone-sub" x="944" y="350">BAGGAGE SERVER · 6 CONTROL-TOWER PCS</text><rect class="zone-rect" x="1000" y="10" width="580" height="145"/><text class="zone-label" x="1024" y="33">03 / EXTERNAL NETWORK</text>';
 let extraZone=state.enterprise?'<rect class="zone-rect" x="1600" y="305" width="480" height="495"/><text class="zone-label" x="1620" y="331">04 / MAINTENANCE &amp; SERVICES</text>':'';
 let html='<defs><filter id="packet-glow"><feGaussianBlur stdDeviation="2"/></filter></defs><g id="topology-scene" transform="translate('+(width/2-width/2*zoom)+','+(height/2-height/2*zoom)+') scale('+zoom+')">'+zones+extraZone;
 for(const l of state.links){const a=engine.get(l.a),b=engine.get(l.b);if(!a||!b)continue;const up=engine.linkUp(l);html+=`<g data-link="${esc(l.id)}" role="button" tabindex="0" aria-label="Cable: ${esc(a.name)} to ${esc(b.name)}"><path class="cable-line ${l.type} ${up?'':'down'}" d="${state.enterprise&&l.type==='serial'&&((l.a==='r1'&&l.b==='r4')||(l.b==='r1'&&l.a==='r4'))?`M${a.x} ${a.y} Q${(a.x+b.x)/2} -90 ${b.x} ${b.y}`:`M${a.x} ${a.y}L${b.x} ${b.y}`}"/><rect class="link-hit" x="0" y="-7" width="${Math.hypot(b.x-a.x,b.y-a.y)}" height="14" transform="translate(${a.x},${a.y}) rotate(${Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI})"/>`;
 if(l.type==='serial'){const horizontal=Math.abs(a.x-b.x)>Math.abs(a.y-b.y);html+=`<text class="link-label" x="${(a.x+b.x)/2+(horizontal?0:12)}" y="${(a.y+b.y)/2-(horizontal?10:0)}" text-anchor="${horizontal?'middle':'start'}">${esc(a.interfaces.find(i=>i.name===l.ai)?.ip||'Unassigned')} · DCE</text>`;}
 html+='</g>';}
 for(const d of state.devices){const up=d.interfaces.some(i=>i.up&&(d.type==='switch'||i.ip)),sel=selected===d.id,ip=d.type==='switch'?`${state.links.filter(l=>(l.a===d.id||l.b===d.id)&&engine.linkUp(l)).length} active ports`:engine.address(d.id);
 html+=`<g class="device-node ${sel?'selected':''}" data-device="${esc(d.id)}" transform="translate(${d.x},${d.y})" tabindex="0" role="button" aria-label="Configure ${esc(d.name)}"><title>${esc(d.name)} · ${esc(ip)}\nClick to configure. Drag to move.</title><rect class="node-halo" x="-43" y="-40" width="86" height="80" rx="19"/><rect class="node-frame" x="-35" y="-32" width="70" height="64" rx="12"/><g class="device-icon">${iconSVG(d.type)}</g><circle class="status-led ${up?'':'down'}" cx="31" cy="-27" r="4"/><text class="device-name" text-anchor="middle" x="0" y="50">${esc(d.name)}</text><text class="device-ip" text-anchor="middle" x="0" y="65">${esc(ip)}</text>${d.type==='router'?`<text class="router-id" text-anchor="middle" y="25">${esc(d.short)}</text>`:''}</g>`;
 }
 svg.innerHTML=html+'</g>';
 $('#device-count').textContent=state.devices.length;$('.nav-item i').textContent=state.devices.length;$('#link-count').textContent=state.links.length;
}
function renderMetrics(){
 const types=new Set(engine.routers.flatMap(r=>[...(r.protocols.ospf.enabled?['OSPF']:[]),...(r.protocols.rip.enabled?['RIP v'+r.protocols.rip.version]:[]),...(r.protocols.bgp?.enabled?['BGP']:[]),...(r.protocols.eigrp?.enabled?['EIGRP']:[])]));
 const staticCount=engine.routers.some(r=>r.routes.length);$('#protocol-label').textContent=types.size?[...types].join(' + '):staticCount?'Static':'Connected';
 const down=state.links.filter(l=>!engine.linkUp(l)).length;$('#health-label').textContent=down?`${down} link${down===1?'':'s'} down`:state.links.length?'Operational':'No links';$('#health-label').style.color=down?'#c17e68':'';
 $('#scenario-label').textContent=scenarios.find(s=>s.id===state.scenario)?.name||'Custom topology';
}
function field(label,name,value,placeholder='',type='text'){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off" spellcheck="false" ${type==='number'?'min="0" max="4294967295"':''}></label>`;}
function deviceOptions(type,chosen){return state.devices.filter(d=>type==='all'?d.type!=='switch':d.type===type).map(d=>`<option value="${esc(d.id)}" ${d.id===chosen?'selected':''}>${esc(d.name)} · ${esc(engine.address(d.id))}</option>`).join('');}
function renderInspector(){
 const panel=$('#inspector'),d=engine.get(selected);
 if(!d){panel.innerHTML='<div class="empty-inspector"><span>↖</span><h3>Your network, in detail.</h3><p>Select any device on the topology to inspect its configuration.</p><button class="btn" id="empty-add">＋ Add a device</button></div>';$('#empty-add').onclick=addDeviceModal;return;}
 const tabs=d.type==='router'?['config','cli','routing','nat','access']:d.type==='switch'?['config']:['config','arp'];if(!tabs.includes(inspectorTab))inspectorTab='config';
 panel.innerHTML=`<div class="inspector-top"><div class="inspector-overline">DEVICE INSPECTOR <button id="close-inspector" aria-label="Deselect device">×</button></div><div class="device-summary"><div class="device-thumbnail">${d.type==='router'?'◎':d.type==='switch'?'▤':d.type==='server'?'▥':'▣'}</div><div><h2>${esc(d.name)}</h2><p>${esc(d.model)}</p></div><span class="device-tag">${esc(d.short?.startsWith('TERM')?'R1':d.short?.startsWith('TWR')?'R2':d.short?.startsWith('ISP')?'R3':d.type.toUpperCase())}</span></div></div><div class="inspector-tabs" role="tablist">${tabs.map(t=>`<button data-inspect-tab="${t}" role="tab" aria-selected="${t===inspectorTab}" class="${t===inspectorTab?'active':''}">${t==='access'?'Access':t==='cli'?'CLI':t==='nat'?'NAT':t==='arp'?'ARP table':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="inspector-body" id="inspector-body"></div>`;
 $('#close-inspector').onclick=()=>{selected=null;renderTopology();renderInspector();};$$('[data-inspect-tab]').forEach(b=>b.onclick=()=>{inspectorTab=b.dataset.inspectTab;renderInspector();});
 if(d.type==='router'){if(inspectorTab==='config')renderRouterConfig(d);if(inspectorTab==='cli')renderCLI(d);if(inspectorTab==='routing')renderRoutingConfig(d);if(inspectorTab==='nat')renderNAT(d);if(inspectorTab==='access')renderAccess(d);}
 else if(d.type==='switch')renderSwitch(d);else if(inspectorTab==='arp')renderARP(d);else renderPCConfig(d);
}
function renderRouterConfig(d){
 let i=engine.port(d,selectedInterface)||d.interfaces[0];selectedInterface=i.name;
 $('#inspector-body').innerHTML=`<div class="field-title">INTERFACE CONFIGURATION <span>IPv4</span></div><form id="interface-form"><label class="field">Network interface<select name="iface">${d.interfaces.map(p=>`<option ${p.name===i.name?'selected':''}>${p.name}</option>`).join('')}</select></label>${field('IP address','ip',i.ip,'e.g. 10.10.10.1')}${field('Subnet mask','mask',i.mask,'255.255.255.224')}<label class="check-field"><input type="checkbox" name="up" ${i.up?'checked':''}> Port enabled <span class="status-chip ${i.up?'':'down'}">${i.up?'UP':'DOWN'}</span></label><div class="interface-up"><span>Network</span><strong>${i.ip?esc(N.network(i.ip,i.mask))+'/'+N.prefix(i.mask):'Unassigned'}</strong></div><button class="btn primary full" type="submit">Apply configuration <span>↗</span></button></form><div class="divider"></div><div class="field-title">ROUTING OVERVIEW</div><div class="protocol-card"><strong>Active protocol</strong><span class="protocol-badge">${d.protocols.eigrp?.enabled?'EIGRP · AS '+d.protocols.eigrp.asn:d.protocols.bgp?.enabled?'BGP · AS '+d.protocols.bgp.asn:d.protocols.ospf.enabled?'OSPF · Process '+d.protocols.ospf.process:d.protocols.rip.enabled?'RIP v'+d.protocols.rip.version:d.routes.length?'Static routing':'Connected only'}</span></div><div class="protocol-card"><strong>Known routes</strong><span>${engine.routes(d).length} routes</span></div><div class="protocol-card"><strong>OSPF neighbors</strong><span>${engine.neighbors(d).length} adjacent</span></div><div class="quick-actions"><button class="btn" id="device-ping">⌁ Test connectivity</button><button class="btn" id="device-routes">⇄ Routes</button></div><div class="inspector-note"><b>Make a connection.</b><br>Configure an interface, then test a path. Changes take effect immediately in this lab.</div>`;
 $('#interface-form [name=iface]').onchange=e=>{selectedInterface=e.target.value;renderRouterConfig(d);};
 $('#interface-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);try{const ip=fd.get('ip').trim(),mask=fd.get('mask').trim();if(ip)N.validateIP(ip,mask);else if(N.prefix(mask)===null)throw Error('Enter a valid subnet mask.');if(ip&&state.devices.some(o=>o.interfaces.some(p=>p!==i&&p.ip===ip)))throw Error('That address is already assigned to another interface.');Object.assign(i,{ip,mask,up:fd.has('up')});changed(d.name+' · '+shortPort(i.name)+' configuration updated.');renderRouterConfig(d);notify('Interface configuration applied.');}catch(err){notify(err.message,true);}};
 $('#device-ping').onclick=()=>toolsModal(d.id);$('#device-routes').onclick=()=>routesModal(d.id);
}
function renderPCConfig(d){const i=d.interfaces[0];$('#inspector-body').innerHTML=`<div class="field-title">DESKTOP CONFIGURATION <span>Static IPv4</span></div><form id="pc-form">${field('IP address','ip',i.ip)}${field('Subnet mask','mask',i.mask)}${field('Default gateway','gateway',d.gateway,'Optional for same-LAN traffic')}<label class="check-field"><input type="checkbox" name="up" ${i.up?'checked':''}> Network interface enabled</label><button class="btn primary full">Apply configuration ↗</button></form><div class="divider"></div><div class="field-title">CONNECTIVITY</div><div class="protocol-card"><strong>Network address</strong><span>${i.ip?esc(N.network(i.ip,i.mask))+'/'+N.prefix(i.mask):'Unassigned'}</span></div><div class="protocol-card"><strong>Interface</strong><span>${i.name}</span></div><div class="quick-actions"><button class="btn" id="pc-ping">⌁ Ping / Traceroute</button></div><div class="inspector-note"><b>Gateway check</b><br>The default gateway must be on the same subnet as this device. A direct peer-to-peer connection can leave it blank.</div>`;
 $('#pc-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const ip=f.get('ip').trim(),mask=f.get('mask').trim(),gateway=f.get('gateway').trim();N.validateIP(ip,mask,gateway);if(state.devices.some(o=>o.id!==d.id&&o.interfaces.some(p=>p.ip===ip)))throw Error('That IP address is already in use.');Object.assign(i,{ip,mask,up:f.has('up')});d.gateway=gateway;d.arp=[];changed(d.name+' IPv4 configuration updated.');renderPCConfig(d);notify('Device configuration applied.');}catch(err){notify(err.message,true);}};$('#pc-ping').onclick=()=>toolsModal(d.id);
}
function renderSwitch(d){$('#inspector-body').innerHTML=`<div class="field-title">ETHERNET PORTS <span>Layer 2</span></div>${d.interfaces.map(i=>{const l=state.links.find(l=>l.a===d.id&&l.ai===i.name||l.b===d.id&&l.bi===i.name),peer=l?engine.get(l.a===d.id?l.b:l.a):null;return `<div class="port-row"><span>${shortPort(i.name)}<small style="display:block;margin-top:5px;font-size:8px;color:#a1b2bf">${peer?esc(peer.name):'Available'}</small></span><button class="status-chip ${i.up?'':'down'}" data-port-toggle="${esc(i.name)}">${i.up?'Enabled':'Disabled'}</button></div>`;}).join('')}<div class="inspector-note"><b>Star topology</b><br>This switch forwards Ethernet frames within a LAN. It does not route traffic between IP subnets. Click a port status to enable or disable it.</div>`;$$('[data-port-toggle]').forEach(b=>b.onclick=()=>{const i=engine.port(d,b.dataset.portToggle);i.up=!i.up;changed(d.name+' '+shortPort(i.name)+(i.up?' enabled.':' disabled.'));renderSwitch(d);});}
function renderARP(d){$('#inspector-body').innerHTML=`<div class="field-title">RESOLVED ADDRESSES</div>${d.arp?.length?`<div class="table-wrap"><table><thead><tr><th>IP ADDRESS</th><th>MAC ADDRESS</th></tr></thead><tbody>${d.arp.map(a=>`<tr><td class="mono">${esc(a.ip)}</td><td class="mono">${esc(a.mac)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small-note">No cached entries. Send a successful ping to resolve a local device or gateway address.</p>'}<div class="inspector-note">MAC addresses are deterministic teaching values. This table records local address resolution after successful ICMP tests.</div><button class="btn full" id="arp-clear">Clear ARP table</button>`;$('#arp-clear').onclick=()=>{d.arp=[];renderARP(d);notify('ARP cache cleared.');};}
function renderCLI(d){
 $('#inspector-body').innerHTML=`<div class="terminal"><div id="cli-output" class="terminal-output" role="log"></div><form class="terminal-line" id="cli-form"><label for="cli-input" id="cli-prompt">${esc(engine.prompt(d))}</label><input id="cli-input" aria-label="Router command" autocomplete="off" spellcheck="false"></form></div><div class="cli-help">Simplified IOS console · ↑/↓ command history<br><button id="cli-reference">Command reference ↗</button></div>`;
 const out=$('#cli-output');out.textContent=d.cli.output.join('\n');out.scrollTop=out.scrollHeight;historyIndex=d.cli.history.length;
 $('#cli-form').onsubmit=e=>{e.preventDefault();const input=$('#cli-input'),cmd=input.value;if(!cmd.trim())return;d.cli.output.push(engine.prompt(d)+' '+cmd);d.cli.history.push(cmd);const result=engine.cli(d,cmd);if(result)d.cli.output.push(result);d.cli.output=d.cli.output.slice(-300);out.textContent=d.cli.output.join('\n');out.scrollTop=out.scrollHeight;input.value='';historyIndex=d.cli.history.length;$('#cli-prompt').textContent=engine.prompt(d);const error=result.startsWith('% ')&&!result.startsWith('%LINK:');if(!error&&/^(ip |no |shutdown|shut$|clock |encapsulation |neighbor |network |version |access-list |hostname |router )/i.test(cmd.trim()))changed(d.short+' · '+cmd);else log(d.short+' · '+cmd,'CLI',error);input.focus();};
 $('#cli-input').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(d.cli.history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.target.value=d.cli.history[historyIndex]||'';}};$('#cli-reference').onclick=commandGuide;
}
function renderRoutingConfig(d){
 if(d.protocols.eigrp)return renderEIGRP(d);
 if(d.protocols.bgp?.enabled)return renderBGPConfig(d);
 const p=d.protocols;const mode=p.ospf.enabled?'ospf':p.rip.enabled?'rip'+p.rip.version:'none';
 $('#inspector-body').innerHTML=`<div class="field-title">DYNAMIC ROUTING</div><form id="protocol-form"><label class="field">Routing protocol<select name="protocol"><option value="none" ${mode==='none'?'selected':''}>Connected / static only</option><option value="rip1" ${mode==='rip1'?'selected':''}>RIP version 1</option><option value="rip2" ${mode==='rip2'?'selected':''}>RIP version 2</option><option value="ospf" ${mode==='ospf'?'selected':''}>OSPF</option></select></label><div id="protocol-fields"></div><button class="btn primary full">Apply routing configuration</button></form><div class="divider"></div><div class="field-title">FORWARDING TABLE <span>${engine.routes(d).length} routes</span></div>${routeTable(d,true)}<div class="quick-actions"><button class="btn" id="add-static">＋ Static route</button><button class="btn" id="view-neighbors">OSPF neighbors</button></div>`;
 const fields=()=>{const v=$('#protocol-form [name=protocol]').value;$('#protocol-fields').innerHTML=v==='ospf'?`${field('OSPF process ID','process',p.ospf.process,'1','number')}<label class="field">Network / wildcard / area<textarea name="networks" spellcheck="false">${esc((p.ospf.networks.length?p.ospf.networks:d.interfaces.filter(i=>i.ip).map(i=>({net:N.network(i.ip,i.mask),wc:N.wildcard(i.mask),area:'0'}))).map(n=>n.net+' '+n.wc+' '+n.area).join('\n'))}</textarea></label><p class="small-note">One network per line: address wildcard area. WAN peers must share an area.</p>`:v.startsWith('rip')?`<label class="field">Participating major networks<textarea name="networks" spellcheck="false">${esc((p.rip.networks.length?p.rip.networks:[...new Set(d.interfaces.filter(i=>i.ip).map(i=>N.network(i.ip,N.classMask(i.ip))))]).join('\n'))}</textarea></label><p class="small-note">One classful major network per line. RIP v2 carries the learned subnet masks.</p>`:'<p class="small-note">Use static routes below, or configure the router in CLI.</p>';};fields();$('#protocol-form [name=protocol]').onchange=fields;
 $('#protocol-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),m=f.get('protocol');try{
  if(m==='ospf'){const process=Number(f.get('process'));if(!Number.isInteger(process)||process<1||process>65535)throw Error('OSPF process ID must be from 1 to 65535.');const networks=f.get('networks').trim().split('\n').filter(Boolean).map(line=>{const a=line.trim().split(/\s+/);if(a.length!==3||N.ipNum(a[0])===null||N.ipNum(a[1])===null||!/^\d+$/.test(a[2])||Number(a[2])>4294967295)throw Error('Each OSPF line needs a network, wildcard and numeric area.');return {net:a[0],wc:a[1],area:String(Number(a[2]))};});p.ospf={enabled:true,process,networks};p.rip.enabled=false;}
  else if(m.startsWith('rip')){const networks=f.get('networks').trim().split(/\s+/).filter(Boolean);if(networks.some(n=>N.ipNum(n)===null))throw Error('Enter valid network addresses for RIP.');p.rip={enabled:true,version:m==='rip1'?1:2,networks:networks.map(n=>N.network(n,N.classMask(n)))};p.ospf.enabled=false;}
  else {p.ospf.enabled=false;p.rip.enabled=false;}changed(d.name+' routing protocol updated.');renderRoutingConfig(d);notify('Routing tables converged.');
 }catch(err){notify(err.message,true);}};
 $('#add-static').onclick=()=>addRouteModal(d);$('#view-neighbors').onclick=()=>neighborsModal(d);
}
function routeTable(d,compact=false){const routes=engine.routes(d);return `<div class="table-wrap"><table><thead><tr><th>TYPE</th><th>DESTINATION</th><th>NEXT HOP</th>${compact?'':'<th>AD / METRIC</th><th>INTERFACE</th>'}</tr></thead><tbody>${routes.map(r=>`<tr><td><span class="route-code">${esc(r.code)}</span></td><td class="mono">${esc(r.net)}/${N.prefix(r.mask)}</td><td class="mono">${r.next==='connected'?'On-link':esc(r.next)}</td>${compact?'':`<td>${r.ad} / ${r.metric}</td><td>${esc(shortPort(r.iface||engine.adjacency().find(e=>e.a===d.id&&e.next===r.next)?.ai||'unresolved'))}</td>`}</tr>`).join('')||'<tr><td colspan="5">No active routes.</td></tr>'}</tbody></table></div>`;}
function renderNAT(d){const n=d.nat;$('#inspector-body').innerHTML=`<div class="field-title">ADDRESS TRANSLATION</div><form id="nat-form"><label class="field">Dynamic translation<select name="mode"><option value="off" ${n.mode==='off'?'selected':''}>Off · static mappings only</option><option value="pat" ${n.mode==='pat'?'selected':''}>PAT · interface overload</option><option value="pool" ${n.mode==='pool'?'selected':''}>Dynamic · address pool</option></select></label>${d.interfaces.map(i=>`<label class="field">${esc(shortPort(i.name))} · ${esc(i.ip||'Unassigned')}<select name="role:${esc(i.name)}"><option value="none" ${i.nat==='none'?'selected':''}>No NAT role</option><option value="inside" ${i.nat==='inside'?'selected':''}>Inside</option><option value="outside" ${i.nat==='outside'?'selected':''}>Outside</option></select></label>`).join('')}<div class="field-row">${field('Allowed source network','acl',n.acl[0]?.net||'10.10.0.0')}${field('ACL wildcard','wildcard',n.acl[0]?.wc||'0.0.255.255')}</div><div id="pool-fields">${field('Pool start','poolStart',n.pools[0]?.start||'172.16.0.10')}${field('Pool end','poolEnd',n.pools[0]?.end||'172.16.0.14')}${field('Pool netmask','poolMask',n.pools[0]?.mask||'255.255.255.248')}</div><button class="btn primary full">Apply NAT configuration</button></form><div class="divider"></div><div class="field-title">TRANSLATION TABLE</div><div class="table-wrap"><table><thead><tr><th>TYPE</th><th>INSIDE LOCAL</th><th>INSIDE GLOBAL</th></tr></thead><tbody>${engine.natTable(d).map(t=>`<tr><td>${esc(t.type)}</td><td class="mono">${esc(t.local)}</td><td class="mono">${esc(t.global)}${t.port?':'+t.port:''}</td></tr>`).join('')||'<tr><td colspan="3">No translations. Send a ping from inside.</td></tr>'}</tbody></table></div><div class="quick-actions"><button class="btn" id="static-nat">＋ Static mapping</button><button class="btn" id="clear-nat">Clear sessions</button></div><div class="inspector-note">The NAT scenarios include outside routes to the translation pool. In other scenarios, add a route to any global address you assign. PAT sessions here model ICMP identifiers.</div>`;
 const toggle=()=>$('#pool-fields').hidden=$('#nat-form [name=mode]').value!=='pool';toggle();$('#nat-form [name=mode]').onchange=toggle;
 $('#nat-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const acl=f.get('acl').trim(),wc=f.get('wildcard').trim(),mode=f.get('mode');if(N.ipNum(acl)===null||N.ipNum(wc)===null)throw Error('Enter valid ACL addresses.');const roles=d.interfaces.map(i=>f.get('role:'+i.name));if(mode!=='off'&&(!roles.includes('inside')||roles.filter(r=>r==='outside').length!==1))throw Error('Choose at least one inside interface and exactly one outside interface.');let pool;if(mode==='pool'){pool={name:'AIRPORT',start:f.get('poolStart').trim(),end:f.get('poolEnd').trim(),mask:f.get('poolMask').trim()};N.validateIP(pool.start,pool.mask);N.validateIP(pool.end,pool.mask);if(N.ipNum(pool.start)>N.ipNum(pool.end)||!N.inNet(pool.end,pool.start,pool.mask))throw Error('Pool endpoints must be ordered and in the same subnet.');}d.interfaces.forEach((i,idx)=>i.nat=roles[idx]);Object.assign(n,{mode,acl:[{id:'1',net:acl,wc}],sourceList:'1',outside:d.interfaces.find(i=>i.nat==='outside')?.name||n.outside});if(pool){n.pools=[pool];n.poolName='AIRPORT';}changed(d.name+' NAT configuration updated.');renderNAT(d);notify('NAT configuration applied.');}catch(err){notify(err.message,true);}};
 $('#static-nat').onclick=()=>staticNATModal(d);$('#clear-nat').onclick=()=>{state.translations=state.translations.filter(t=>t.router!==d.id);renderNAT(d);log(d.name+' dynamic NAT sessions cleared.');};
}
function openModal(title,body,eyebrow='AERONET WORKSPACE'){animationToken++;$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function scenarioModal(){openModal('Choose your flight plan',`<p class="modal-intro">Start with a configured network or build your understanding one connection at a time. Loading a scenario replaces the current lab; Save lab first to keep it.</p><div class="scenario-grid">${scenarios.map(s=>`<button class="scenario-card" data-scenario="${s.id}"><span class="scenario-icon">${s.icon}</span><strong>${s.name}</strong><small>${s.desc}</small><span class="scenario-exp">${s.exp}</span></button>`).join('')}</div>`,'SCENARIO LIBRARY · 15 SCENARIOS');$$('[data-scenario]').forEach(b=>b.onclick=()=>loadScenario(b.dataset.scenario));}
function loadScenario(kind,lab=null){animationToken++;state=N.makeScenario(kind);if(lab)state.lab=lab;engine=new N.Engine(state);selected=state.devices.find(d=>d.type==='router')?.id||state.devices[0].id;inspectorTab='config';selectedInterface='GigabitEthernet0/0';lastPacket=null;setTool('select');zoom=1;$('#zoom-label').textContent='100%';closeModal();renderAll();log((scenarios.find(s=>s.id===kind)?.name||kind)+' loaded. Ready to explore.','SCENARIO');notify('Scenario loaded.');}
function routesModal(chosen=selected){const r=engine.get(chosen)?.type==='router'?chosen:engine.routers[0]?.id;openModal('Routing tables',engine.routers.length?`<p class="modal-intro">Packets follow the longest matching prefix. Connected routes take precedence, followed by static routes, OSPF and RIP for equal prefixes.</p><label class="field">Router<select id="route-router">${deviceOptions('router',r)}</select></label><div id="full-routes"></div><div class="modal-actions"><button class="btn" id="route-neighbors">OSPF neighbors</button><button class="btn primary" id="route-add">＋ Add static route</button></div>`:'<p class="modal-intro">This topology has no routers. Add a router or load an airport scenario.</p>');if(!engine.routers.length)return;
 const render=()=>{const d=engine.get($('#route-router').value);$('#full-routes').innerHTML=routeTable(d)+`<p class="small-note">C = connected · S = static · S* = default · R = RIP · O = OSPF · O IA = OSPF inter-area · B = eBGP · D = EIGRP</p>`+(d.routes.length?`<h3>Configured static routes</h3>${d.routes.map((s,idx)=>`<div class="port-row"><span class="mono">${esc(s.net)}/${N.prefix(s.mask)} → ${esc(s.next)}</span><button class="text-btn danger-btn" data-remove-route="${idx}">Remove</button></div>`).join('')}`:'');$$('[data-remove-route]').forEach(b=>b.onclick=()=>{d.routes.splice(Number(b.dataset.removeRoute),1);changed(d.name+' static route removed.');render();renderInspector();});};render();$('#route-router').onchange=render;$('#route-add').onclick=()=>addRouteModal(engine.get($('#route-router').value));$('#route-neighbors').onclick=()=>neighborsModal(engine.get($('#route-router').value));}
function addRouteModal(d){openModal('Add a static route',`<p class="modal-intro">${esc(d.name)} · Use 0.0.0.0 with mask 0.0.0.0 for a default route. The next hop must be a reachable router interface.</p><form id="static-route-form">${field('Destination network','net','10.20.10.0')}${field('Subnet mask','mask','255.255.255.224')}${field('Next-hop address','next','172.16.0.2')}<div class="modal-actions"><button type="button" class="btn" id="route-cancel">Back to routes</button><button class="btn primary">Add route</button></div></form>`);$('#route-cancel').onclick=()=>routesModal(d.id);$('#static-route-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{engine.addRoute(d,f.get('net').trim(),f.get('mask').trim(),f.get('next').trim());changed(d.name+' static route added.');renderInspector();routesModal(d.id);notify('Static route added.');}catch(err){notify(err.message,true);}};}
function neighborsModal(d){const neighbors=engine.neighbors(d);openModal('OSPF neighbors',`<p class="modal-intro">${esc(d.name)} · A FULL adjacency requires enabled interfaces, matching WAN subnets, participating OSPF networks and matching areas.</p><div class="table-wrap"><table><thead><tr><th>NEIGHBOR</th><th>STATE</th><th>ADDRESS</th><th>INTERFACE</th><th>AREA</th><th>COST</th></tr></thead><tbody>${neighbors.map(n=>`<tr><td>${esc(n.router)}</td><td><span class="status-chip">FULL</span></td><td class="mono">${esc(n.ip)}</td><td>${shortPort(n.iface)}</td><td>${esc(n.area)}</td><td>${n.cost}</td></tr>`).join('')||'<tr><td colspan="6">No OSPF adjacencies. Check both ends of each WAN link.</td></tr>'}</tbody></table></div><div class="inspector-note">OSPF uses cost 1 on Ethernet and 64 on serial in this model. Routers joining different areas need an area 0 interface. Convergence is immediate.</div><div class="modal-actions"><button class="btn" id="neighbors-back">Back to routes</button></div>`);$('#neighbors-back').onclick=()=>routesModal(d.id);}
function staticNATModal(d){openModal('Static NAT mapping',`<p class="modal-intro">${esc(d.name)} · Create a fixed inside-local to inside-global mapping. Inside/outside interface roles and routes must also be configured.</p><form id="static-nat-form">${field('Inside local address','local','10.10.10.10')}${field('Inside global address','global','172.16.0.10')}<button class="btn primary full">Add mapping</button></form>${d.nat.static.length?`<h3>Existing mappings</h3>${d.nat.static.map((t,i)=>`<div class="port-row"><span class="mono">${esc(t.local)} → ${esc(t.global)}</span><button class="text-btn danger-btn" data-remove-nat="${i}">Remove</button></div>`).join('')}`:''}`);$('#static-nat-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),local=f.get('local').trim(),global=f.get('global').trim();if(N.ipNum(local)===null||N.ipNum(global)===null)return notify('Enter valid IPv4 addresses.',true);d.nat.static=d.nat.static.filter(n=>n.local!==local&&n.global!==global);d.nat.static.push({local,global});changed(d.name+' static NAT mapping added.');renderInspector();closeModal();notify('Static mapping added.');};$$('[data-remove-nat]').forEach(b=>b.onclick=()=>{d.nat.static.splice(Number(b.dataset.removeNat),1);changed(d.name+' static NAT mapping removed.');renderInspector();staticNATModal(d);});}
function toolsModal(source=selected){const src=engine.get(source)?.type!=='switch'&&engine.get(source)?source:state.devices.find(d=>d.type==='pc')?.id||state.devices.find(d=>d.type!=='switch')?.id;const dst=state.devices.find(d=>d.id==='p6')?.id||state.devices.find(d=>d.id!==src&&d.type!=='switch')?.id;
 openModal('Test a connection',`<p class="modal-intro">Follow a packet through your airport. Ping checks both directions; traceroute shows the forward path and its router hops.</p><form id="network-tool-form"><div class="tool-form"><label class="field">Source device<select name="source" id="test-source">${deviceOptions('all',src)}</select></label><label class="field">Destination device<select name="dest" id="test-dest">${deviceOptions('all',dst)}<option value="custom">Custom IP / NAT global…</option></select></label></div><div id="custom-destination" hidden>${field('Destination IPv4 address','target','172.16.0.10')}</div><div class="network-tool-buttons"><button class="btn primary" name="action" value="ping">⌁ Send ping</button><button class="btn" name="action" value="trace">⇢ Traceroute</button><span class="small-note">ICMP · 4 echo requests · TTL 32</span></div></form><div id="tool-result" class="tool-results">Ready when you are. Choose two devices and send a packet.</div><div id="hop-path" class="hop-path"></div><div class="modal-actions"><button class="btn" id="return-topology">Return to topology</button></div>`,'NETWORK TOOLS · ICMP / TRACEROUTE');
 $('#test-dest').onchange=e=>$('#custom-destination').hidden=e.target.value!=='custom';$('#network-tool-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),source=f.get('source'),dest=f.get('dest')==='custom'?f.get('target').trim():f.get('dest');runTest(source,dest,e.submitter?.value||'ping');};$('#return-topology').onclick=closeModal;
}
function runTest(source,dest,action){
 const result=engine.ping(source,dest,{dry:action==='trace'});const sourceName=engine.get(source)?.name||source,targetName=engine.get(dest)?.name||dest;const path=(result.path||[]).filter(id=>engine.get(id));
 const routers=path.filter(id=>engine.get(id).type==='router'&&id!==source);let output;
 if(action==='ping')output=`PING ${result.targetIP||dest} from ${result.sourceIP||engine.address(source)} · 32 bytes\n\n`+(result.ok?Array.from({length:4},(_,i)=>`Reply from ${result.targetIP}: bytes=32 time=${2+routers.length*3+i}ms TTL=${64-routers.length}`).join('\n'):`Request timed out.\n${result.reason}`)+`\n\nPackets: sent = 4, received = ${result.ok?4:0}, lost = ${result.ok?0:4} (${result.ok?0:100}% loss)\n`+(result.ok?'✓ Echo request and reply paths verified.':'× '+result.reason);
 else {const steps=path.filter(id=>engine.get(id).type==='router'||id===path.at(-1)).filter(id=>id!==source);output=`TRACEROUTE to ${result.targetIP||dest} · maximum 32 hops\n\n`+steps.map((id,i)=>`${String(i+1).padStart(2)}  ${engine.get(id).name.padEnd(24)} ${engine.address(id).padEnd(15)} ${3+i*4} ms`).join('\n')+`\n\n${result.ok?'✓ Destination reached. Reply path also verified.':'× '+result.reason}`;}
 const box=$('#tool-result');if(box){box.className='tool-results '+(result.ok?'success':'failure');box.textContent=output;$('#hop-path').innerHTML=path.map(id=>`<span class="hop-chip">${esc(engine.get(id).name)}</span>`).join('<span class="hop-arrow">→</span>');}
 lastPacket={...result,sourceName,targetName,action,time:time()};state.packets.unshift(lastPacket);state.packets=state.packets.slice(0,25);log(`${action==='trace'?'Traceroute':'Ping'} · ${sourceName} → ${targetName} · ${result.ok?'Successful':result.reason}`,action==='trace'?'TRACE':'ICMP',!result.ok);renderInspector();animatePacket(path,result.ok?result.returnPath:[],result.ok);notify(result.ok?'Packet delivered. Return path verified.':result.reason,!result.ok);
}
async function animatePacket(path,reply=[],success=true){const token=++animationToken;const svg=$('#topology-scene');if(!svg||path.length<2)return;const ns='http://www.w3.org/2000/svg';const dot=document.createElementNS(ns,'circle');dot.setAttribute('r','7');dot.setAttribute('class','packet-dot');if(!success)dot.style.fill='#d69a64';svg.append(dot);const points=[...path,...(reply.length?reply.slice(1):[])].map(id=>engine.get(id)).filter(Boolean);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(let i=1;i<points.length;i++){if(token!==animationToken)break;const a=points[i-1],b=points[i],start=performance.now(),duration=reduced?1:470;await new Promise(resolve=>{function frame(now){const t=Math.min(1,(now-start)/duration);dot.setAttribute('cx',a.x+(b.x-a.x)*t);dot.setAttribute('cy',a.y+(b.y-a.y)*t);if(t<1&&token===animationToken)requestAnimationFrame(frame);else resolve();}requestAnimationFrame(frame);});}dot.remove();}
function subnetModal(){openModal('Make room for every connection',`<p class="modal-intro">Plan airport LANs with /27 subnets and WAN links with /30 subnets. Enter any host address and prefix to calculate its network.</p><form id="subnet-form"><div class="tool-form">${field('IPv4 address / prefix','cidr','10.10.10.10/27','192.168.1.10/27')}<div style="display:flex;align-items:center"><button class="btn primary">Calculate subnet ↗</button></div></div></form><div id="subnet-output"></div><div class="inspector-note">/31 is treated as a point-to-point network with two usable addresses. /32 represents a single host. For /0–/30, network and broadcast addresses are excluded from the host range.</div>`,'EXPERIMENT 04 · SUBNETTING IN WAN');const calc=()=>{try{const s=N.subnet($('#subnet-form [name=cidr]').value);$('#subnet-output').innerHTML=`<div class="subnet-results">${[['Network address',s.network+'/'+s.prefix],['Subnet mask',s.mask],['Broadcast / upper address',s.broadcast],['Wildcard mask',s.wildcard],['First usable address',s.first],['Last usable address',s.last],['Usable hosts',s.usable.toLocaleString()],['Total addresses',s.total.toLocaleString()]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>`;}catch(e){$('#subnet-output').innerHTML=`<p class="inline-error">${esc(e.message)}</p>`;}};$('#subnet-form').onsubmit=e=>{e.preventDefault();calc();};calc();}
function guideModal(exp){const list=exp?[{...experiments[exp-1],num:exp}]:experiments.map((e,i)=>({...e,num:i+1}));openModal(exp?experiments[exp-1].title:'Your airport. Twelve experiments.',`<p class="modal-intro">Based on the experiment sequence in the 2025–26 Computer Networks lab manual. Use this workspace to explore each concept and inspect what happens to a packet.</p><div class="lab-guide-grid">${list.map(e=>`<article class="guide-card"><div class="guide-number">EXPERIMENT ${String(e.num).padStart(2,'0')}</div><h3>${e.title}</h3><p>${e.body}</p><button data-guide-scenario="${e.scenario}" data-guide-lab="${e.num}">Load suggested scenario ↗</button></article>`).join('')}</div><h3>How the model works</h3><p class="small-note">Configuration changes converge immediately. OSPF uses a simplified shortest-path calculation; RIP uses shortest hop counts, a 15-hop limit and classful summaries for v1. The lab checks active cables, masks, gateways, next hops and the echo reply path. It does not send real traffic or implement timers, full protocol state machines, VLANs, STP, or every IOS command. DCE clock rate is stored for practice; serial timing is abstracted.</p><div class="modal-actions"><button class="btn" id="guide-commands">View command reference</button><button class="btn primary" id="guide-subnet">Open subnet calculator</button></div>`,'COMPUTER NETWORKS · LAB FIELD GUIDE');$$('[data-guide-scenario]').forEach(b=>b.onclick=()=>loadScenario(b.dataset.guideScenario,Number(b.dataset.guideLab)));$('#guide-commands').onclick=commandGuide;$('#guide-subnet').onclick=subnetModal;}
function commandGuide(){openModal('A small console. Real concepts.',`<p class="modal-intro">Select a router, open CLI, and enter one command per line. Names such as g0/0 and s0/0/0 resolve to full interface names. Unknown commands return an explanation.</p><h3>Interface & static routing</h3><pre class="code-block">enable
configure terminal
interface g0/0
ip address 10.10.10.1 255.255.255.224
no shutdown
exit
ip route 0.0.0.0 0.0.0.0 172.16.0.2
end
show ip route
show ip interface brief</pre><h3>RIP v2</h3><pre class="code-block">configure terminal
router rip
version 2
network 10.0.0.0
network 172.16.0.0
end</pre><h3>OSPF · example for Terminal Router</h3><pre class="code-block">configure terminal
router ospf 1
network 10.10.10.0 0.0.0.31 area 1
network 10.10.20.0 0.0.0.31 area 1
network 172.16.0.0 0.0.0.3 area 0
end
show ip ospf neighbor</pre><h3>NAT overload · example for Terminal Router</h3><pre class="code-block">configure terminal
interface g0/0
ip nat inside
exit
interface s0/0/0
ip nat outside
exit
access-list 1 permit 10.10.0.0 0.0.255.255
ip nat inside source list 1 interface s0/0/0 overload
end
show ip nat translations</pre><h3>Static & dynamic NAT</h3><pre class="code-block">configure terminal
ip nat inside source static 10.10.10.10 172.16.0.10
ip nat pool AIRPORT 172.16.0.10 172.16.0.14 netmask 255.255.255.248
access-list 1 permit 10.10.0.0 0.0.255.255
ip nat inside source list 1 pool AIRPORT
end
show running-config</pre><p class="small-note">NAT needs inside/outside roles plus reachable global-address routes. Load a NAT scenario for a prepared example. Use Network tools for ping and traceroute.</p>`,'CISCO-STYLE CLI · COMMAND REFERENCE');}
function addDeviceModal(){openModal('Add to your airport',`<p class="modal-intro">New devices start without an IP address. Add a device, then use the Cable tool to connect an available port.</p><form id="add-device-form"><label class="field">Device type<select name="type"><option value="pc">PC · workstation</option><option value="server">Server</option><option value="switch">Switch · 24 Ethernet ports</option><option value="router">Router · 2 Ethernet + 2 serial</option></select></label>${field('Device name','name','','e.g. Gate B12 workstation')}<button class="btn primary full">Add device</button></form>`);$('#add-device-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),id='d'+Date.now().toString(36),name=f.get('name').trim().slice(0,35)||'New '+type;let d;if(type==='router'){d=N.router(id,name,'RTR-'+(engine.routers.length+1),550,350,[N.iface('GigabitEthernet0/0'),N.iface('GigabitEthernet0/1'),N.iface('Serial0/0/0','','255.255.255.252'),N.iface('Serial0/0/1','','255.255.255.252')]);d.interfaces.forEach(i=>i.up=false);}else if(type==='switch')d=N.sw(id,name,550,350);else d=N.pc(id,name,'','',550,350,type);state.devices.push(d);selected=id;inspectorTab='config';changed(name+' added to topology.');renderInspector();closeModal();notify('Device added. Drag it into position, then connect a cable.');};}
function selectDevice(id){if(tool==='delete'){const d=engine.get(id);openModal('Remove '+d.name+'?',`<p class="modal-intro">This removes the device and its ${state.links.filter(l=>l.a===id||l.b===id).length} attached cables from the current topology. You can restore the original scenario with Reset.</p><div class="modal-actions"><button class="btn" id="cancel-delete">Keep device</button><button class="btn dark" id="confirm-delete">Remove device</button></div>`);$('#cancel-delete').onclick=closeModal;$('#confirm-delete').onclick=()=>{state.devices=state.devices.filter(d=>d.id!==id);state.links=state.links.filter(l=>l.a!==id&&l.b!==id);if(selected===id)selected=null;changed(d.name+' removed.');renderInspector();closeModal();};return;}
 if(tool==='cable'){if(!cableStart){cableStart=id;$('#canvas-hint').textContent=engine.get(id).name+' selected · Choose another device';notify('Choose the second device.');return;}if(cableStart===id)return notify('Choose a different device.',true);const a=cableStart,b=id,type=$('#cable-type').value;cableStart=null;try{const l=engine.addLink(a,b,type);changed(engine.get(a).name+' ↔ '+engine.get(b).name+' cable connected.');notify(engine.linkUp(l)?'Cable connected. Link is up.':'Cable attached, but link is down. Check cable type and enabled ports.',!engine.linkUp(l));renderInspector();}catch(err){notify(err.message,true);}$('#canvas-hint').textContent='Choose two devices to connect';return;}
 selected=id;inspectorTab='config';renderTopology();renderInspector();}
function setTool(t){tool=t;cableStart=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#cable-options').hidden=t!=='cable';$('#canvas-hint').textContent=t==='select'?'Click a device to configure · Drag to arrange':t==='cable'?'Choose two devices to connect':'Click a cable to remove · Click a device to review removal';}
function renderActivity(){if(!$('#activity-content'))return;$('#event-count').textContent=state.events.length;const container=$('#activity-content');if(logTab==='events'){container.innerHTML=state.events.map(e=>`<div class="event-row ${e.error?'error':''}"><time>${esc(e.time)}</time><span class="event-symbol">${e.error?'×':'✓'}</span><span class="event-message">${esc(e.message)}</span><span class="event-kind">${esc(e.kind)}</span></div>`).join('')||'<p class="small-note">No events yet. Configure a device or test a connection.</p>';}else {const p=lastPacket;container.innerHTML=p?`<div class="packet-summary"><span class="status-chip ${p.ok?'':'down'}">${p.ok?'DELIVERED':'DROPPED'}</span> <strong>${esc(p.sourceName)} → ${esc(p.targetName)}</strong> · ICMP · ${esc(p.time)}<br>${esc(p.reason)}</div>${(p.steps||[]).map(s=>`<div class="event-row"><time>${s.reply?'REPLY':'ECHO'}</time><span class="event-symbol">→</span><span class="event-message">${esc(s.device)} · ${esc(s.action)}</span><span></span></div>`).join('')}`:'<p class="small-note">Send a ping or traceroute to inspect forwarding decisions and NAT translations.</p>';}}
function renderExperiments(){$('#experiment-list').innerHTML=experiments.map((e,i)=>`<button class="exp-item ${state.lab===i+1?'active':''}" data-exp="${i+1}" aria-current="${state.lab===i+1?'step':'false'}"><span class="exp-num">${String(i+1).padStart(2,'0')}</span><span>${e.topic}</span><span class="exp-indicator" aria-hidden="true">${state.lab===i+1?'↗':''}</span></button>`).join('');$$('[data-exp]').forEach(b=>b.onclick=()=>{state.lab=Number(b.dataset.exp);renderExperiments();guideModal(state.lab);});}
function saveLab(){try{localStorage.setItem('aeronet-lab-v1',JSON.stringify({...state,packets:[],events:state.events.slice(0,25)}));log('Workspace saved in this browser.','SAVED');notify('Lab saved in this browser.');}catch(e){notify('Browser storage unavailable. Allow local storage to save this lab.',true);}}
function restoreLab(){try{const raw=localStorage.getItem('aeronet-lab-v1');if(!raw)return notify('No saved lab yet. Use Save lab to keep your configuration.');const s=JSON.parse(raw);validateSaved(s);state=s;state.events=Array.isArray(s.events)?s.events:[];state.translations=[];state.packets=[];engine=new N.Engine(state);selected=state.devices[0]?.id||null;inspectorTab='config';lastPacket=null;setTool('select');renderAll();log('Saved lab restored.','SAVED');notify('Your saved lab is restored.');}catch(e){notify('Could not restore this lab: '+e.message,true);}}
function validateSaved(s){if(s.version!==1||!Array.isArray(s.devices)||!Array.isArray(s.links)||s.devices.length>100||s.links.length>500)throw Error('Unsupported saved format.');const ids=new Set();for(const d of s.devices){if(!d.id||ids.has(d.id)||!['router','pc','server','switch'].includes(d.type)||!Array.isArray(d.interfaces)||!Number.isFinite(d.x)||!Number.isFinite(d.y))throw Error('Invalid device data.');ids.add(d.id);for(const i of d.interfaces){if(typeof i.name!=='string'||i.ip&&(N.ipNum(i.ip)===null||N.prefix(i.mask)===null))throw Error('Invalid interface data.');}if(d.type==='router'&&(!d.protocols?.ospf||!d.protocols?.rip||!d.nat||!d.cli||!Array.isArray(d.routes)))throw Error('Invalid router data.');}for(const l of s.links)if(!ids.has(l.a)||!ids.has(l.b)||!['straight','cross','serial'].includes(l.type))throw Error('Invalid link data.');}
function renderAll(){renderTopology();renderMetrics();renderInspector();renderActivity();renderExperiments();}
// Pointer movement is converted from screen coordinates to the SVG viewbox.
let drag=null;
$('#topology').addEventListener('pointerdown',e=>{const node=e.target.closest('[data-device]');if(!node||tool!=='select')return;const d=engine.get(node.dataset.device),p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('#topology-scene').getScreenCTM().inverse());drag={id:d.id,x:d.x,y:d.y,startX:p.x,startY:p.y,moved:false,pointer:e.pointerId};$('#topology').setPointerCapture(e.pointerId);});
$('#topology').addEventListener('pointermove',e=>{if(!drag)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('#topology-scene').getScreenCTM().inverse()),dx=p.x-drag.startX,dy=p.y-drag.startY;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;if(!drag.moved)return;const d=engine.get(drag.id);const peer=state.scenario==='p2p';d.x=Math.max(65,Math.min(peer?1035:state.enterprise?2035:1535,drag.x+dx));d.y=Math.max(60,Math.min(peer?580:730,drag.y+dy));renderTopology();});
$('#topology').addEventListener('pointerup',e=>{if(!drag)return;const info=drag;drag=null;if(info.moved){animationToken++;log(engine.get(info.id).name+' repositioned.','TOPOLOGY');}else selectDevice(info.id);});
$('#topology').addEventListener('pointercancel',()=>drag=null);
$('#topology').addEventListener('click',e=>{const node=e.target.closest('[data-device]');if(node&&tool!=='select'){selectDevice(node.dataset.device);return;}const link=e.target.closest('[data-link]');if(!link)return;const l=state.links.find(l=>l.id===link.dataset.link);if(tool==='delete'){state.links=state.links.filter(s=>s.id!==l.id);changed('Cable removed between '+engine.get(l.a).name+' and '+engine.get(l.b).name+'.');renderInspector();notify('Cable removed.');}else notify(engine.get(l.a).name+' '+shortPort(l.ai)+' ↔ '+engine.get(l.b).name+' '+shortPort(l.bi)+' · '+(engine.linkUp(l)?'Link up':'Link down'));});
$('#topology').addEventListener('keydown',e=>{const node=e.target.closest('[data-device]');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectDevice(node.dataset.device);return;}const link=e.target.closest('[data-link]');if(link&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const l=state.links.find(l=>l.id===link.dataset.link);if(tool==='delete'){state.links=state.links.filter(s=>s.id!==l.id);changed('Cable removed.');renderInspector();notify('Cable removed.');}else notify(engine.get(l.a).name+' ↔ '+engine.get(l.b).name+' · '+(engine.linkUp(l)?'Link up':'Link down'));}});
$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#cancel-cable').onclick=()=>setTool('select');$('#cable-type').onchange=()=>{cableStart=null;$('#canvas-hint').textContent='Choose two devices to connect';};
$('#zoom-in').onclick=()=>{zoom=Math.min(1.8,+(zoom+.1).toFixed(1));$('#zoom-label').textContent=Math.round(zoom*100)+'%';renderTopology();};$('#zoom-out').onclick=()=>{zoom=Math.max(.6,+(zoom-.1).toFixed(1));$('#zoom-label').textContent=Math.round(zoom*100)+'%';renderTopology();};$('#fit-button').onclick=()=>{zoom=1;$('#zoom-label').textContent='100%';renderTopology();notify('Topology fitted to workspace.');};
$('#scenario-button').onclick=scenarioModal;$('#add-button').onclick=addDeviceModal;$('#help-button').onclick=()=>guideModal();$('#guide-button').onclick=()=>guideModal();$('#save-button').onclick=saveLab;
$('#reset-button').onclick=()=>{openModal('Reset this scenario?',`<p class="modal-intro">Restore the original ${esc(scenarios.find(s=>s.id===state.scenario)?.name||'airport')} topology and configuration. Your browser’s saved lab will remain available.</p><div class="modal-actions"><button class="btn" id="cancel-reset">Keep working</button><button class="btn dark" id="confirm-reset">Reset scenario</button></div>`);$('#cancel-reset').onclick=closeModal;$('#confirm-reset').onclick=()=>loadScenario(state.scenario);};
$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$$('[data-logtab]').forEach(b=>b.onclick=()=>{logTab=b.dataset.logtab;$$('[data-logtab]').forEach(t=>t.classList.toggle('active',t===b));renderActivity();});$('#clear-log').onclick=()=>{if(logTab==='events')state.events=[];else{lastPacket=null;state.packets=[];}renderActivity();notify('Log cleared.');};
$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='routes')routesModal();if(b.dataset.view==='tools')toolsModal();if(b.dataset.view==='subnet')subnetModal();if(b.dataset.view==='topology')closeModal();});
$('#clock').textContent='CLIENT-SIDE · REAL-TIME';renderAll();log('EIGRP AS 100 converged · 4 routers with redundant WAN paths.','ROUTING');log('Airport topology ready. Select a device to get started.','SYSTEM');

// Keep topology labels from being selected or copied during device interactions.
const topologyWorkspace=$('.topology-wrap');
['copy','cut','dragstart'].forEach(type=>topologyWorkspace.addEventListener(type,e=>e.preventDefault()));

function renderBGPConfig(d){
 const p=d.protocols.bgp;
 $('#inspector-body').innerHTML=`<div class="field-title">EXPERIMENT 10 · eBGP</div><form id="bgp-form">${field('Local AS number','asn',p.asn,'65001','number')}<label class="field">Neighbors · IP / remote AS<textarea name="peers">${esc(p.neighbors.map(n=>n.ip+' '+n.asn).join('\n'))}</textarea></label><label class="field">Advertised networks · network / mask<textarea name="nets">${esc(p.networks.map(n=>n.net+' '+n.mask).join('\n'))}</textarea></label><p class="small-note">One entry per line. Only exact connected prefixes originate. Peers must configure reciprocal IPs and AS numbers.</p><button class="btn primary full">Apply BGP configuration</button></form><h3>Sessions</h3>${engine.bgpNeighbors(d).map(n=>`<div class="port-row"><span>${esc(n.ip)} · AS ${n.asn}</span><strong>${n.state}</strong></div>`).join('')||'<p>No neighbors configured.</p>'}<h3>Learned prefixes</h3><pre class="code-block">${esc(engine.cli(d,'show ip bgp'))}</pre>${routeTable(d,true)}`;
 $('#bgp-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),asn=+f.get('asn');try{if(!Number.isInteger(asn)||asn<1||asn>4294967295)throw Error('Invalid AS number.');const lines=k=>f.get(k).trim().split('\n').filter(Boolean).map(l=>l.trim().split(/\s+/));const neighbors=lines('peers').map(a=>{if(a.length!==2||N.ipNum(a[0])===null||!Number.isInteger(+a[1])||+a[1]<1||+a[1]>4294967295)throw Error('Use IP REMOTE-AS for each neighbor.');return {ip:a[0],asn:+a[1]};});const networks=lines('nets').map(a=>{if(a.length!==2)throw Error('Use NETWORK MASK.');if(N.ipNum(a[0])===null||N.prefix(a[1])===null)throw Error('Invalid network or mask.');if(N.network(a[0],a[1])!==a[0])throw Error('Use a network address.');return {net:a[0],mask:a[1]};});Object.assign(p,{asn,neighbors,networks});changed(d.name+' BGP configuration updated.');renderBGPConfig(d);}catch(err){notify(err.message,true);}};
}
// Append serial controls after each inspector render without replacing existing forms.
const baseInspector=renderInspector;
renderInspector=function(){baseInspector();const d=engine.get(selected);if(d?.type!=='router'||inspectorTab!=='config')return;const box=document.createElement('div');box.innerHTML='<div class="divider"></div><div class="field-title">SERIAL ENCAPSULATION · EXPERIMENT 09</div>'+d.interfaces.filter(i=>i.name.startsWith('Serial')).map(i=>`<label class="field">${esc(i.name)}<select data-serial="${esc(i.name)}"><option value="hdlc" ${(i.encapsulation||'hdlc')==='hdlc'?'selected':''}>HDLC</option><option value="ppp" ${i.encapsulation==='ppp'?'selected':''}>PPP</option></select></label>`).join('')+'<p class="small-note">Both serial endpoints must use the same encapsulation. A mismatch takes the link down.</p>';$('#inspector-body').append(box);$$('[data-serial]',box).forEach(el=>el.onchange=()=>{engine.port(d,el.dataset.serial).encapsulation=el.value;changed(d.name+' '+el.dataset.serial+' encapsulation '+el.value.toUpperCase());});};
renderInspector();

function renderEIGRP(d){const p=d.protocols.eigrp;$('#inspector-body').innerHTML=`<div class="field-title">EXPERIMENT 11 · EIGRP</div><form id="eigrp-form">${field('Autonomous system','asn',p.asn,'100','number')}<label class="field">Network / wildcard<textarea name="networks">${esc(p.networks.map(n=>n.net+' '+n.wc).join('\n'))}</textarea></label><label class="check-field"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}> Enable EIGRP</label><button class="btn primary full">Apply EIGRP configuration</button></form><h3>EIGRP neighbors</h3><pre class="code-block">${esc(engine.cli(d,'show ip eigrp neighbors'))}</pre><h3>Forwarding table</h3>${routeTable(d,true)}<p class="small-note">D = EIGRP, AD 90. Fixed teaching costs: serial 2169856, Ethernet 28160. Disable an interface in Config to observe alternate paths.</p>`;$('#eigrp-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),asn=+f.get('asn');if(!Number.isInteger(asn)||asn<1||asn>65535)throw Error('EIGRP AS must be 1–65535.');const networks=f.get('networks').trim().split('\n').filter(Boolean).map(l=>{const a=l.trim().split(/\s+/);if(a.length!==2||N.ipNum(a[0])===null||N.ipNum(a[1])===null)throw Error('Use NETWORK WILDCARD on each line.');return {net:a[0],wc:a[1]};});Object.assign(p,{asn,networks,enabled:f.has('enabled')});changed(d.name+' EIGRP updated.');renderEIGRP(d);}catch(err){notify(err.message,true);}};}
function remoteModal(d){const m=d.management||(d.management={domain:'',username:'',password:'',keys:false,sshVersion:2,transport:[],loginLocal:false});openModal('Telnet & SSH · Remote management',`<p class="modal-intro">Browser-local teaching sessions. Demo login: admin / AirportLab123. Telnet represents cleartext access; SSH represents encrypted access. No real encryption or sockets are used.</p><form id="management-form">${field('Domain name','domain',m.domain)}${field('Local username','username',m.username)}${field('Lab password','password',m.password,'Demo password','password')}<label class="check-field"><input name="keys" type="checkbox" ${m.keys?'checked':''}> Simulated RSA keys / SSH v2</label><label class="check-field"><input name="telnet" type="checkbox" ${m.transport.includes('telnet')?'checked':''}> Permit Telnet</label><label class="check-field"><input name="ssh" type="checkbox" ${m.transport.includes('ssh')?'checked':''}> Permit SSH</label><button class="btn primary">Apply VTY configuration</button></form><div class="divider"></div><form id="remote-form"><label class="field">Source device<select name="source">${deviceOptions('pc','p1')}</select></label><label class="field">Target router interface<select name="target">${d.interfaces.filter(i=>i.ip).map(i=>`<option>${esc(i.ip)}</option>`).join('')}</select></label><label class="field">Transport<select name="transport"><option value="ssh">SSH</option><option value="telnet">Telnet</option></select></label>${field('Login username','username','admin')}${field('Login password','password','','Enter lab password','password')}<button class="btn primary">Connect</button></form><pre class="code-block" id="remote-output" role="log">Ready to connect.</pre><form id="remote-command" hidden><label class="field">Remote IOS command<input name="command" autocomplete="off" placeholder="show ip route"></label><button class="btn">Send command</button><button type="button" id="remote-disconnect" class="btn">Disconnect</button></form>`);let session;
 $('#management-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);Object.assign(m,{domain:f.get('domain').trim(),username:f.get('username').trim(),password:f.get('password'),keys:f.has('keys'),sshVersion:2,loginLocal:true,transport:['telnet','ssh'].filter(k=>f.has(k))});changed(d.name+' VTY configuration updated.');notify('Remote access settings applied.');};
 $('#remote-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{session=engine.remoteConnect(f.get('source'),f.get('target'),f.get('transport'),f.get('username'),f.get('password'));$('#remote-output').textContent='Connected via '+session.transport.toUpperCase()+' to '+d.short+'\n'+engine.prompt(d);$('#remote-command').hidden=false;}catch(err){session=null;$('#remote-command').hidden=true;$('#remote-output').textContent=err.message;}};
 $('#remote-command').onsubmit=e=>{e.preventDefault();const input=e.target.elements.command,cmd=input.value;if(!session?.active)return;$('#remote-output').textContent+='\n'+engine.prompt(d)+' '+cmd+'\n'+engine.remoteCommand(session,cmd);input.value='';if(!session.active)e.target.hidden=true;changed(d.name+' remote command executed.');};$('#remote-disconnect').onclick=()=>{if(session)session.active=false;$('#remote-command').hidden=true;$('#remote-output').textContent+='\nDisconnected.';};
}
const serialInspector=renderInspector;
renderInspector=function(){serialInspector();const d=engine.get(selected);if(d?.type==='router'&&inspectorTab==='config'){const b=document.createElement('button');b.className='btn primary full';b.textContent='Telnet / SSH · Remote access';b.onclick=()=>remoteModal(d);$('#inspector-body').append(b);}};
renderInspector();

function renderAccess(d){const m=d.management;$('#inspector-body').innerHTML=`<div class="access-card"><span class="access-icon">⌘</span><div class="field-title">EXPERIMENT 12</div><h3>Manage from anywhere.</h3><p>Configure router access, then connect from an airport workstation.</p><div class="protocol-card"><strong>SSH v2</strong><span class="status-chip ${m?.keys?'':'down'}">${m?.keys?'KEYS READY':'NOT CONFIGURED'}</span></div><div class="protocol-card"><strong>VTY transports</strong><span>${esc(m?.transport?.join(' + ').toUpperCase()||'NONE')}</span></div><div class="protocol-card"><strong>Router address</strong><span class="mono">${esc(engine.address(d.id))}</span></div><button class="btn primary full" id="open-access">Open remote management ↗</button><p class="small-note">Try SSH and Telnet, change a password, or disable a transport to explore access controls.</p></div>`;$('#open-access').onclick=()=>remoteModal(d);}
// A reversible WAN failure makes redundant forwarding easy to demonstrate.
const failoverButton=document.createElement('button');failoverButton.className='btn';failoverButton.id='wan-failover';failoverButton.textContent='⇄ WAN failover';failoverButton.title='Toggle the terminal-to-tower serial link in the expanded airport';$('#fit-button').parentElement.append(failoverButton);
failoverButton.onclick=()=>{if(!state.enterprise)return notify('Load Expanded airport · EIGRP to explore WAN failover.');const i=engine.port(engine.get('r1'),'Serial0/0/0');i.up=!i.up;failoverButton.textContent=i.up?'⇄ WAN failover':'↻ Restore WAN';changed(i.up?'Primary WAN restored.':'Primary WAN disabled. EIGRP uses the maintenance backup path.');renderInspector();};
